from pathlib import Path
from html.parser import HTMLParser
from urllib.parse import urljoin, urlsplit
import hashlib, json, re

source = 'https://help.payhip.com/'
path = Path('products/services/catalogue-payhip/official-help.html')
body = path.read_bytes()

class HelpLinks(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.anchor = None
        self.links = {}

    def handle_starttag(self, tag, attrs):
        if tag == 'a':
            href = dict(attrs).get('href')
            self.anchor = (href, []) if href else None

    def handle_data(self, data):
        if self.anchor:
            self.anchor[1].append(data)

    def handle_endtag(self, tag):
        if tag != 'a' or not self.anchor:
            return
        href, parts = self.anchor
        self.anchor = None
        label = ' '.join(''.join(parts).split())
        url = urljoin(source, href)
        parsed = urlsplit(url)
        if parsed.scheme == 'https' and parsed.hostname in {'help.payhip.com', 'payhip.com', 'www.payhip.com'} and re.search(r'pay|stripe|canad|fee|pric|payout', label + ' ' + parsed.path, re.I):
            self.links[url] = label

parser = HelpLinks()
parser.feed(body.decode('utf-8', errors='replace'))
result = {'source': source, 'sha256': hashlib.sha256(body).hexdigest(), 'official_links': [{'url': url, 'label': label} for url, label in sorted(parser.links.items())], 'evidence_limit': 'Help-center navigation is a lead. It does not establish fees, Canadian eligibility, payout terms, or checkout activation.'}
output = path.with_name('official-help-link-screen.json')
output.write_text(json.dumps(result, indent=2, ensure_ascii=False) + '\n', encoding='utf-8')
print(output.read_text(encoding='utf-8'))
